namespace MinCms.Test.Shared.Support
{
    using System;
    using System.IO;
    using System.Threading;
    using System.Threading.Tasks;

    /// <summary>
    /// Non-seekable stream of generated bytes that stands in for an S3 response body.
    /// It can hold back data until released, fail partway through, and reports how much
    /// was consumed and whether it was disposed, so tests can observe streaming behavior.
    /// </summary>
    public sealed class ControlledReadStream : Stream
    {
        private readonly long _Length;
        private readonly long? _GateAfter;
        private readonly long? _FailAfter;
        private readonly TaskCompletionSource _Gate = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        private readonly TaskCompletionSource _Disposed = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        private long _Position;

        /// <summary>Instantiate.</summary>
        /// <param name="length">Total bytes the stream produces.</param>
        /// <param name="gateAfter">Hold back data after this many bytes until <see cref="Release"/> is called.</param>
        /// <param name="failAfter">Throw <see cref="IOException"/> after this many bytes.</param>
        public ControlledReadStream(long length, long? gateAfter = null, long? failAfter = null)
        {
            _Length = length;
            _GateAfter = gateAfter;
            _FailAfter = failAfter;
        }

        /// <summary>Bytes handed to the reader so far.</summary>
        public long BytesConsumed => Interlocked.Read(ref _Position);

        /// <summary>Completes when the stream has been disposed.</summary>
        public Task DisposedTask => _Disposed.Task;

        /// <summary>Let a gated stream continue past its gate.</summary>
        public void Release() => _Gate.TrySetResult();

        /// <summary>The byte expected at a given position.</summary>
        public static byte ByteAt(long position) => (byte)(position % 251);

        /// <inheritdoc />
        public override bool CanRead => true;

        /// <inheritdoc />
        public override bool CanSeek => false;

        /// <inheritdoc />
        public override bool CanWrite => false;

        /// <inheritdoc />
        public override long Length => throw new NotSupportedException();

        /// <inheritdoc />
        public override long Position
        {
            get => BytesConsumed;
            set => throw new NotSupportedException();
        }

        /// <inheritdoc />
        public override void Flush()
        {
        }

        /// <inheritdoc />
        public override int Read(byte[] buffer, int offset, int count)
        {
            return ReadAsync(buffer.AsMemory(offset, count)).AsTask().GetAwaiter().GetResult();
        }

        /// <inheritdoc />
        public override Task<int> ReadAsync(byte[] buffer, int offset, int count, CancellationToken cancellationToken)
        {
            return ReadAsync(buffer.AsMemory(offset, count), cancellationToken).AsTask();
        }

        /// <inheritdoc />
        public override async ValueTask<int> ReadAsync(Memory<byte> buffer, CancellationToken cancellationToken = default)
        {
            long position = BytesConsumed;
            if (_FailAfter.HasValue && position >= _FailAfter.Value)
            {
                throw new IOException("Simulated storage failure.");
            }

            if (_GateAfter.HasValue && position >= _GateAfter.Value)
            {
                await _Gate.Task.WaitAsync(cancellationToken).ConfigureAwait(false);
            }

            long limit = _Length;
            if (_FailAfter.HasValue) limit = Math.Min(limit, _FailAfter.Value);
            if (_GateAfter.HasValue && !_Gate.Task.IsCompleted) limit = Math.Min(limit, _GateAfter.Value);

            int count = (int)Math.Min(buffer.Length, limit - position);
            if (count <= 0) return 0;

            Span<byte> span = buffer.Span;
            for (int i = 0; i < count; i++)
            {
                span[i] = ByteAt(position + i);
            }

            Interlocked.Add(ref _Position, count);
            return count;
        }

        /// <inheritdoc />
        public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();

        /// <inheritdoc />
        public override void SetLength(long value) => throw new NotSupportedException();

        /// <inheritdoc />
        public override void Write(byte[] buffer, int offset, int count) => throw new NotSupportedException();

        /// <inheritdoc />
        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                _Disposed.TrySetResult();
            }

            base.Dispose(disposing);
        }
    }
}
